with open('C:/Users/User/vex_rag_pipeline/output/joy_of_vex_rag.jsonl', 'r', encoding='utf-8') as f:
    for line in f:
        rec = json.loads(line)
        normalized = ' '.join(rec['code'].split()).strip()
        if normalized not in code_to_best:
            code_to_best[normalized] = rec
        else:
            if len(rec.get('explanation', '')) > len(code_to_best[normalized].get('explanation', '')):
                code_to_best[normalized] = rec

# Analyze code length distribution (lines) 
for big_cat in ['math_operations', 'geometry_manipulation', 'point_clouds', 'color']:
    entries = [r for r in code_to_best.values() if r['category'] == big_cat]
    code_lines = []
    for r in entries:
        lines = len(r['code'].strip().split('\n'))
        code_lines.append(lines)

    line_dist = Counter()
    for l in code_lines:
        if l <= 1:
            line_dist['1 line'] += 1
        elif l <= 3:
            line_dist['2-3 lines'] += 1
        elif l <= 6:
            line_dist['4-6 lines'] += 1
        elif l <= 10:
            line_dist['7-10 lines'] += 1
        else:
            line_dist['11+ lines'] += 1

    print(f'{big_cat}: {len(entries)} entries')
    print(f'  Code length: {dict(sorted(line_dist.items()))}')

    # Estimate markdown lines: header(2) + code block(lines+2) + explanation(2) + link(1) + blank(1)
    total_md_lines = sum(2 + len(r['code'].strip().split('\\n')) + 2 + 2 + 1 + 1 for r in entries)
    print(f'  Estimated markdown lines: ~{total_md_lines}')
    print()
"

