        if normalized not in code_to_best:
            code_to_best[normalized] = rec
        else:
            if len(rec.get('explanation', '')) > len(code_to_best[normalized].get('explanation', '')):
                code_to_best[normalized] = rec

# For math_operations, classify by dominant function
math_entries = [r for r in code_to_best.values() if r['category'] == 'math_operations']

# Subcategorize
subcats = Counter()
for r in math_entries:
    funcs = set(r.get('vex_functions', []))
    if 'quaternion' in funcs or '@orient' in funcs:
        subcat = 'quaternions_orientation'
    elif any(f in funcs for f in ['sin', 'cos', '$PI', '$TAU']):
        subcat = 'trigonometry'
    elif any(f in funcs for f in ['fit', 'clamp', 'smooth', 'chramp']):
        subcat = 'remapping_clamping'
    elif any(f in funcs for f in ['cross', 'dot', 'normalize', 'length']):
        subcat = 'vector_math'
    elif any(f in funcs for f in ['matrix3', 'matrix', 'maketransform', 'cracktransform']):
        subcat = 'matrices'
    else:
        subcat = 'general_math'
    subcats[subcat] += 1

print('math_operations subcategories:')
for sub, count in sorted(subcats.items(), key=lambda x: -x[1]):
    print(f'  {sub}: {count}')

# For geometry_manipulation
